mapper.select:
SELECT exp_per_book
FROM erp_bookstore_exp_rule
WHERE schoolyear = #{schoolyear}

SELECT TOP 1 center_code
FROM erp_student
WHERE student_id = #{studentId}

SELECT TOP 1 grade_key
FROM erp_student
WHERE student_id = #{studentId}

SELECT TOP 1 i.bcode
FROM erp_bookstore_item i
JOIN erp_bookstore_item_center ic ON ic.bcode = i.bcode AND ic.center_code = #{centerCode}
WHERE i.content_id = #{contentId}
  AND ic.quantity - ic.loaned_qty - ic.lost_qty > 0
ORDER BY ic.registered_at ASC
